static bool is_palindrome( string t )
{
    const char *char_data = t.c_str();

    for( const char *start = char_data, *stop = char_data + t.length() - 1; start < stop; ++start, --stop )
    {
        while( !isalpha(*start) )
            ++start;
        while( !isalpha(*stop) )
            --stop;
        if( tolower(*start) != tolower(*stop) )
            return false;
    }

    return true;
}

